<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetVersion\Domain\Gateway;

use Civi\Lughauth\Features\Document\SnippetVersion\Domain\SnippetVersion;

class SnippetVersionCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(SnippetVersion $snippetVersion, ?int $size): SnippetVersionCursor
    {
        $next = clone $this;
        $next->sinceUid = $snippetVersion->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
